+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
+                    + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\\.)+"
+                    + "[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])$");
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<Message> messagesGrid = new Grid<>();
+    private final MessageStore messageStore;
+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        nameField.setWidthFull();
+        emailField.setWidthFull();
+        phoneField.setWidthFull();
+        messageField.setWidthFull();
+        messageField.setMinHeight("8em");
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        sendButton.addClickListener(event -> sendMessage());
+        nameField.addValueChangeListener(event -> reenableSendButton());
+        emailField.addValueChangeListener(event -> reenableSendButton());
+        phoneField.addValueChangeListener(event -> reenableSendButton());
+        messageField.addValueChangeListener(event -> reenableSendButton());
+
+        // Enter submits from any field, including the message area.
+        Shortcuts.addShortcutListener(this, event -> sendMessage(), Key.ENTER);
+
+        messagesGrid.addColumn(Message::name).setHeader("Name");
+        messagesGrid.addColumn(Message::message).setHeader("Message");
+        messagesGrid.setWidthFull();
+        refreshMessages();
+
+        add(nameField, emailField, phoneField, messageField, sendButton,
+                new H2("Messages"), messagesGrid);
+        setMaxWidth("48rem");
+        setPadding(true);
+        setSpacing(true);
+    }
+
+    private void reenableSendButton() {
+        sendButton.setEnabled(true);
+    }
+
+    private void sendMessage() {
+        boolean valid = true;
+
+        String name = nameField.getValue();
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        String message = messageField.getValue();
+
+        boolean nameMissing = name == null || name.isBlank();
+        nameField.setInvalid(nameMissing);
+        nameField.setErrorMessage(nameMissing ? "Name is required" : "");
+        valid &= !nameMissing;
+
+        boolean emailGiven = email != null && !email.isBlank();
+        boolean phoneGiven = phone != null && !phone.isBlank();
+        boolean emailInvalid = emailGiven && !isValidEmail(email);
+        boolean noContactMethod = !emailGiven && !phoneGiven;
+        boolean emailFieldInvalid = emailInvalid || noContactMethod;
+        emailField.setInvalid(emailFieldInvalid);
+        emailField.setErrorMessage(emailInvalid
+                ? "Enter a valid e-mail address"
+                : noContactMethod ? "Give an e-mail address or a phone number" : "");
+        valid &= !emailFieldInvalid;
+
+        boolean messageMissing = message == null || message.isBlank();
+        boolean messageTooLong = message != null && message.length() > MAX_MESSAGE_LENGTH;
+        messageField.setInvalid(messageMissing || messageTooLong);
+        messageField.setErrorMessage(messageMissing
+                ? "Message is required"
+                : messageTooLong ? "Message must be at most 500 characters" : "");
+        valid &= !messageMissing && !messageTooLong;
+
+        if (!valid) {
+            return;
+        }
+
+        messageStore.add(new Message(name, email, phone, message));
+        refreshMessages();
+        Notification.show("Message sent");
+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        clearValidation();
+        sendButton.setEnabled(false);
+    }
+
+    private boolean isValidEmail(String email) {
+        // Empty input is handled by the contact-method rule.
+        return EMAIL_PATTERN.matcher(email).matches();
+    }
+
+    private void clearValidation() {
+        nameField.setInvalid(false);
+        nameField.setErrorMessage("");
+        emailField.setInvalid(false);
+        emailField.setErrorMessage("");
+        messageField.setInvalid(false);
+        messageField.setErrorMessage("");
+    }
+
+    private void refreshMessages() {
+        messagesGrid.setItems(messageStore.getNewestFirst());
+    }
+
+    private boolean hasUnsavedInput() {
+        return hasText(nameField.getValue()) || hasText(emailField.getValue())
+                || hasText(phoneField.getValue()) || hasText(messageField.getValue());
+    }
+
+    private boolean hasText(String value) {
+        return value != null && !value.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        var continueNavigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Paragraph("You have unsent changes. Do you want to discard them?"));
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            continueNavigation.cancel();
+            dialog.close();
+            remove(dialog);
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            remove(dialog);
+            continueNavigation.proceed();
+        });
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        add(dialog);
+        dialog.open();
+    }
+}
